INSERT INTO `projects` (`id`, `name`, `project_type`, `description`, `status`, `start_date`, `end_date`, `manager_id`, `created_by`, `created_at`, `updated_at`) VALUES (1,'ShopEase – Nền tảng thương mại điện tử','agile','Xây dựng lại toàn bộ website bán hàng trực tuyến: catalog, giỏ hàng, thanh toán VNPay/MoMo, tìm kiếm và gợi ý sản phẩm. Mục tiêu tăng tỷ lệ chuyển đổi 25%.','active','2026-07-16','2026-12-03',4,4,'2026-07-13 09:00:00','2026-10-07 09:00:00'),(2,'Mobile Banking App v2','agile','Phiên bản 2 của ứng dụng ngân hàng di động: eKYC, chuyển khoản nhanh 24/7, thanh toán hóa đơn bằng QR và xác thực sinh trắc học.','active','2026-07-30','2026-11-27',5,5,'2026-07-27 09:00:00','2026-10-07 09:00:00'),(3,'Cổng thông tin nhân sự (HR Portal)','waterfall','Cổng nội bộ để nhân viên xem phiếu lương, đăng ký nghỉ phép và tra cứu quy định công ty. Đã nghiệm thu và bàn giao.','completed','2026-05-11','2026-09-18',6,6,'2026-05-08 09:00:00','2026-10-07 09:00:00'),(4,'Data Warehouse & BI Dashboard','waterfall','Xây dựng kho dữ liệu tập trung và dashboard BI cho ban điều hành. Dự án đang chậm tiến độ do chất lượng nguồn dữ liệu CRM/ERP kém.','at_risk','2026-06-20','2026-10-28',4,4,'2026-06-17 09:00:00','2026-10-07 09:00:00'),(5,'Hệ thống CRM Bán hàng','agile','CRM quản lý khách hàng tiềm năng, cơ hội bán hàng và báo cáo doanh số cho phòng Kinh doanh. Dự án đang trong giai đoạn lập kế hoạch.','inactive','2026-10-18','2027-02-05',6,6,'2026-10-05 09:00:00','2026-10-07 09:00:00'),(6,'Website Marketing & Landing Page Q4','agile','Làm mới website giới thiệu và bộ landing page cho chiến dịch Q4: giảm tỷ lệ thoát, tăng lead đăng ký dùng thử 30%.','active','2026-09-03','2026-11-02',5,5,'2026-08-31 09:00:00','2026-10-07 09:00:00'),(7,'Chuyển đổi hạ tầng sang Kubernetes','waterfall','Di chuyển các dịch vụ từ VM sang Kubernetes. Tạm dừng do chờ phê duyệt ngân sách hạ tầng cloud quý tới.','on_hold','2026-08-09','2026-12-07',6,6,'2026-08-06 09:00:00','2026-10-07 09:00:00'),(8,'Hệ thống chấm công & tính lương','agile','Tự động hóa chấm công (vân tay, GPS), tính lương, thuế TNCN và bảo hiểm; tích hợp với HR Portal.','active','2026-08-19','2026-11-17',6,6,'2026-08-16 09:00:00','2026-10-07 09:00:00'),(9,'Chatbot chăm sóc khách hàng','agile','Chatbot AI trả lời tự động câu hỏi thường gặp trên website và Zalo, chuyển tiếp nhân viên khi cần.','active','2026-09-10','2026-12-07',5,5,'2026-09-07 09:00:00','2026-10-07 09:00:00'),(10,'Nâng cấp quy trình QA Automation','agile','Xây dựng bộ kiểm thử tự động cho các sản phẩm chính, tích hợp CI để giảm 60% thời gian kiểm thử hồi quy.','active','2026-09-17','2026-11-12',4,4,'2026-09-14 09:00:00','2026-10-07 09:00:00'),(11,'ERP Kế toán & Tài chính','waterfall','Phân hệ kế toán tổng hợp cho ERP nội bộ: sổ cái, công nợ phải thu/phải trả và báo cáo tài chính theo thông tư hiện hành.','active','2026-06-10','2026-11-22',4,4,'2026-06-07 09:00:00','2026-10-07 09:00:00'),(12,'Cổng đối tác B2B','agile','Cổng đặt hàng dành cho đại lý và nhà phân phối: bảng giá theo cấp, đặt hàng số lượng lớn, công nợ và theo dõi vận đơn.','active','2026-08-13','2026-11-19',5,5,'2026-08-10 09:00:00','2026-10-07 09:00:00'),(13,'Ứng dụng giao hàng nội thành','agile','Ứng dụng cho tài xế và khách hàng: nhận đơn, tối ưu lộ trình, theo dõi vị trí và xác nhận giao hàng bằng ảnh/chữ ký.','active','2026-08-27','2026-12-03',5,5,'2026-08-24 09:00:00','2026-10-07 09:00:00'),(14,'Hệ thống Helpdesk & Ticket','agile','Hệ thống tiếp nhận và xử lý yêu cầu hỗ trợ nội bộ (IT, nhân sự, hành chính) với SLA, phân loại tự động và báo cáo. Đã bàn giao.','completed','2026-05-31','2026-09-26',6,6,'2026-05-28 09:00:00','2026-10-07 09:00:00'),(15,'Migration cơ sở dữ liệu MySQL → PostgreSQL','waterfall','Chuyển đổi CSDL các hệ thống lõi từ MySQL sang PostgreSQL. Đang chậm do khác biệt kiểu dữ liệu và stored procedure cũ.','at_risk','2026-07-25','2026-11-02',4,4,'2026-07-22 09:00:00','2026-10-07 09:00:00'),(16,'Bảo mật hệ thống & Pentest','waterfall','Đánh giá rủi ro, kiểm thử xâm nhập các ứng dụng chính, khắc phục lỗ hổng và xây dựng chính sách bảo mật theo ISO 27001.','active','2026-08-29','2026-11-27',6,6,'2026-08-26 09:00:00','2026-10-07 09:00:00'),(17,'Số hóa quy trình Onboarding nhân sự','agile','Tự động hóa hồ sơ, hợp đồng, cấp tài khoản và đào tạo hội nhập cho nhân viên mới.','active','2026-09-08','2026-11-25',6,6,'2026-09-05 09:00:00','2026-10-07 09:00:00'),(18,'Chương trình Loyalty & Voucher cho ShopEase','agile','Tích điểm, hạng thành viên và voucher khuyến mãi cho ShopEase nhằm tăng tỷ lệ khách hàng quay lại.','active','2026-09-17','2026-12-10',4,4,'2026-09-14 09:00:00','2026-10-07 09:00:00'),(19,'Analytics thời gian thực','agile','Luồng dữ liệu sự kiện thời gian thực (Kafka) phục vụ dashboard vận hành và phát hiện bất thường.','active','2026-08-20','2026-11-17',4,4,'2026-08-17 09:00:00','2026-10-07 09:00:00'),(20,'Design System dùng chung','agile','Thư viện component và token thiết kế dùng chung cho các sản phẩm web/mobile, có Storybook và hướng dẫn sử dụng.','active','2026-08-06','2026-11-05',5,5,'2026-08-03 09:00:00','2026-10-07 09:00:00'),(21,'Cải tiến hiệu năng & Observability','waterfall','Chuẩn hóa tracing, metrics, log tập trung và tối ưu hiệu năng các dịch vụ lõi. Đang chờ khởi động sau khi dự án Kubernetes được duyệt.','inactive','2026-10-28','2027-01-16',6,6,'2026-10-05 09:00:00','2026-10-07 09:00:00'),(22,'Chiến dịch Social & Content Q4','agile','Kế hoạch nội dung mạng xã hội và influencer cho mùa mua sắm cuối năm, phối hợp với dự án Website Marketing.','active','2026-09-10','2026-11-12',5,5,'2026-09-07 09:00:00','2026-10-07 09:00:00'),(23,'Cổng thanh toán & Đối soát nội bộ','agile','Tập trung hóa kết nối ngân hàng, ví điện tử và đối soát giao dịch tự động cho toàn bộ sản phẩm của công ty; giảm thời gian đối soát cuối ngày từ 4 giờ xuống dưới 30 phút.','active','2026-07-23','2026-11-12',4,4,'2026-07-20 09:00:00','2026-10-07 09:00:00'),(24,'Nền tảng học tập trực tuyến (LMS)','agile','Hệ thống đào tạo nội bộ và cho đối tác: khóa học video, bài kiểm tra, chứng chỉ điện tử và theo dõi tiến độ học tập theo phòng ban.','active','2026-07-09','2026-11-26',5,5,'2026-07-06 09:00:00','2026-10-07 09:00:00'),(25,'Quản lý kho thông minh (WMS)','agile','Số hóa nghiệp vụ kho: nhập – xuất – kiểm kê bằng mã vạch trên thiết bị cầm tay, gợi ý vị trí kệ và cảnh báo tồn kho tối thiểu.','active','2026-08-06','2026-12-17',6,6,'2026-08-03 09:00:00','2026-10-07 09:00:00'),(26,'Cổng tuyển dụng & quản lý ứng viên (ATS)','agile','Quản lý toàn bộ quy trình tuyển dụng từ đăng tin, sàng lọc hồ sơ, lịch phỏng vấn đến thư mời nhận việc. Đã nghiệm thu và đang vận hành.','completed','2026-05-21','2026-09-24',6,6,'2026-05-18 09:00:00','2026-10-07 09:00:00');
