INSERT INTO `task_comments` (`id`, `task_id`, `user_id`, `content`, `created_at`) VALUES (1,36,7,'Nhớ cấu hình analyzer tiếng Việt (bỏ dấu) để tìm \'ao so mi\' ra \'áo sơ mi\' nhé.','2026-10-04 10:15:00'),(2,36,11,'OK anh, em đang thử icu_analyzer, sáng mai em gửi kết quả trên staging.','2026-10-05 10:15:00'),(3,41,4,'Task này đã quá hạn, @[Nguyễn Hoài Nam](usr-19) ưu tiên fix trong hôm nay vì ảnh hưởng checkout.','2026-10-07 10:15:00'),(4,41,19,'Em đã tìm ra nguyên nhân: làm tròn 2 lần ở utils/currency. Em đang viết test lại.','2026-10-07 10:15:00'),(5,24,23,'Đã test sandbox: hủy thanh toán giữa chừng vẫn giữ đơn ở trạng thái chờ. Cần xác nhận với PM.','2026-09-20 10:15:00'),(6,26,26,'Đã cập nhật spec nút \'Đặt hàng\' theo feedback của PM, mọi người xem lại Figma giúp mình.','2026-09-18 10:15:00'),(7,51,16,'Staging đã chạy được pipeline build, còn thiếu bước deploy tự động lên môi trường UAT.','2026-10-06 10:15:00'),(8,80,9,'Trên iOS quét ổn, Android 9 vẫn lỗi do camera API cũ, em tách thành task riêng.','2026-09-29 10:15:00'),(9,82,22,'Đã reproduce được lỗi trên máy Samsung J7. Đang thử dùng ML Kit thay ZXing.','2026-10-05 10:15:00'),(10,90,21,'FaceID đã chạy, vân tay Android cần xử lý trường hợp người dùng thêm vân tay mới (invalidate key).','2026-10-07 10:15:00'),(11,90,5,'Đúng, bên Bảo mật yêu cầu bắt đăng nhập lại khi có thay đổi sinh trắc học.','2026-10-07 10:15:00'),(12,152,15,'Dữ liệu CRM thiếu mã khách hàng ở 18% bản ghi, em đã gửi danh sách cho phòng Kinh doanh bổ sung.','2026-10-02 10:15:00'),(13,152,4,'Task này đang chậm so với kế hoạch. Anh sẽ làm việc với trưởng phòng Kinh doanh để đẩy nhanh.','2026-10-03 10:15:00'),(14,153,14,'Cần quy tắc gộp khách hàng trùng (cùng SĐT khác tên). Em đề xuất ưu tiên SĐT + email.','2026-10-04 10:15:00'),(15,163,28,'Phòng Kế toán muốn thêm bộ lọc theo kỳ kế toán, em đã cập nhật yêu cầu.','2026-10-05 10:15:00'),(16,275,32,'Lưu ý từ 2026 có thay đổi mức giảm trừ, chị đã gửi văn bản vào thư mục tài liệu.','2026-10-03 10:15:00'),(17,275,13,'Em đã cập nhật hằng số giảm trừ thành cấu hình để không phải sửa code khi luật đổi.','2026-10-04 10:15:00'),(18,264,23,'Đối soát 120 nhân viên mẫu: 119 khớp, 1 lệch do làm tròn phụ cấp ăn trưa.','2026-09-26 10:15:00'),(19,306,11,'Đã import 500 FAQ, truy vấn ngữ nghĩa trả lời đúng ~85%. Cần thêm dữ liệu cho nhóm câu hỏi hoàn tiền.','2026-10-05 10:15:00'),(20,316,18,'Widget bundle hiện 90KB gzip, em sẽ tách lazy load để không ảnh hưởng điểm Lighthouse của website.','2026-10-07 10:15:00'),(21,315,5,'Zalo OA đã được duyệt. Thắng lấy key production ở thư mục bảo mật chung nhé.','2026-10-06 10:15:00'),(22,205,26,'Bộ 3 mẫu landing đã export, bản mobile ở frame \'Mobile-v2\'.','2026-09-29 10:15:00'),(23,214,20,'Form lead đã nối API tạm, chờ marketing xác nhận field bắt buộc.','2026-10-06 10:15:00'),(24,338,23,'Dùng chung fixture đăng nhập với team Mobile để đỡ trùng lặp.','2026-10-06 10:15:00'),(25,235,6,'Dự án tạm dừng chờ ngân sách. Giữ nguyên tiến độ hiện tại, sẽ mở lại khi có phê duyệt.','2026-09-21 10:15:00'),(26,431,11,'Đã có cảnh báo khi đại lý vượt 80% hạn mức, còn thiếu luồng xin nâng hạn mức tạm thời.','2026-10-06 10:15:00'),(27,431,5,'Bên kinh doanh xác nhận chỉ cần cảnh báo, chưa cần luồng duyệt nâng hạn mức ở bản đầu.','2026-10-07 10:15:00'),(28,490,11,'Thử thuật toán nearest-neighbor trước, so sánh với OR-Tools khi có đủ dữ liệu thực tế.','2026-10-05 10:15:00'),(29,573,15,'Còn 14/60 procedure dùng cursor lồng nhau, chuyển sang set-based sẽ mất thêm vài ngày.','2026-10-02 10:15:00'),(30,573,4,'Dự án đang chậm, anh sẽ báo cáo rủi ro lên CTO và đề xuất bổ sung nhân lực.','2026-10-03 10:15:00'),(31,639,7,'Dùng truy vấn tham số hóa cho toàn bộ module, đừng chỉ vá riêng endpoint này.','2026-10-06 10:15:00'),(32,756,16,'Cluster 3 broker đã chạy ổn, đang cấu hình retention 7 ngày cho topic sự kiện.','2026-08-31 10:15:00'),(33,827,19,'Đã hỗ trợ sắp xếp đa cột, phần virtual scroll sẽ làm ở bản sau.','2026-09-14 10:15:00'),(34,668,12,'Đã tích hợp nhà cu